from pathlib import Path
from html import escape as esc
import json,re
from xml.sax.saxutils import escape as xml
R=Path(__file__).resolve().parents[1]; D=R/'dist'
BASE='https://tlcoke2.github.io/healthy-concept-medical-centre/'
articles=json.loads((R/'content/articles.json').read_text())
raw=(D/'index.html').read_text()
header=raw[raw.index('<header>'):raw.index('</header>')+9]
header=re.sub(r'href="#', 'href="./index.html#',header)
footer=raw[raw.index('<footer>'):raw.index('</footer>')+9]
footer=re.sub(r'href="#','href="./index.html#',footer)
nav='<nav class="hub-nav" aria-label="Patient information"><a href="./health.html">Health & wellness</a><a href="./blog.html">Clinic blog</a><a href="./news.html">Health news</a><a href="./local-services.html">Local services</a></nav>'
def page(file,title,description,body):
 url=BASE+file
 html=f'''<!doctype html><html lang="en-JM"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{esc(title)} | Healthy Concept Medical Centre</title><meta name="description" content="{esc(description,quote=True)}"><meta name="theme-color" content="#174e43"><link rel="canonical" href="{url}"><meta property="og:type" content="{'article' if file.startswith('article-') else 'website'}"><meta property="og:title" content="{esc(title,quote=True)}"><meta property="og:description" content="{esc(description,quote=True)}"><meta property="og:url" content="{url}"><meta name="twitter:card" content="summary"><link rel="icon" href="./favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="./styles.css"><link rel="stylesheet" href="./hub.css"><link rel="alternate" type="application/rss+xml" title="Healthy Concept clinic blog" href="./feed.xml"><script src="./config.js" defer></script><script src="./hub.js" defer></script><script src="./assistant.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><div class="topbar"><span>Health information for our Montego Bay community</span><a href="tel:+18766695974">Call +1 876 669 5974 ↗</a></div>{header}{nav}<main id="main">{body}<section class="wrap share-section"><h2>Useful to someone you know?</h2><p>Share this page with family, friends or your community.</p><div class="share-links" data-share></div><p role="status" class="share-status fine"></p></section><section class="hub-cta wrap"><div><p class="eyebrow">TAKE YOUR NEXT STEP</p><h2>Questions about your care?</h2><p>General doctor consultations from JA$3,000. Our clinic team can help you arrange a visit.</p></div><a class="button" href="./index.html#appointment">Request an appointment ↗</a></section></main>{footer}</body></html>'''
 (D/file).write_text(html)
def intro(kicker,title,desc):return f'<section class="wrap hub-hero"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{desc}</p></section>'
def link(url,title):return f'<a href="{esc(url,quote=True)}" target="_blank" rel="noopener noreferrer">{esc(title)} ↗</a>'
resources=[('Food & nutrition','Understand balanced eating with familiar foods.','https://www.moh.gov.jm/programmes-policies/food-based-dietary-guidelines/','Food Based Dietary Guidelines'),('Move for wellbeing','Explore the Ministry’s physical activity guidance.','https://www.moh.gov.jm/physical-activity/','Physical Activity'),('Mental wellbeing','Find official information about mental health and wellbeing.','https://www.moh.gov.jm/mental-health-wellness/','Mental Health & Wellness'),('Patient education','Browse public education materials, including disease prevention resources.','https://www.moh.gov.jm/public-education-resources/','Public Education Resources')]
cards=''.join(f'<article class="hub-card"><p class="eyebrow">MOHW JAMAICA</p><h2>{a}</h2><p>{b}</p>{link(c,d)}</article>' for a,b,c,d in resources)
page('health.html','Health & wellness','Trusted health information and Ministry of Health & Wellness Jamaica resources.',intro('LEARN. ASK. TAKE CARE.','Small steps.<br>Better-informed choices.','Explore clear information, official Jamaican health resources and practical questions to bring to your next consultation.')+f'<section class="wrap hub-grid">{cards}</section><section class="wrap editorial-note"><h2>Information you can trace</h2><p>These links lead to the Ministry of Health & Wellness, Jamaica. Healthy Concept Medical Centre is not affiliated with or endorsed by these external organisations. Health information is general education, not individual diagnosis or treatment. Publication dates and guidance can change; check the original source.</p><p>Sources checked 21 October 2026. For personal advice, arrange a consultation.</p></section>')
cards=''.join(f'<article class="hub-card filterable" data-category="{esc(a["category"])}"><p class="eyebrow">{esc(a["category"])}</p><h2><a href="./article-{a["slug"]}.html">{esc(a["title"])}</a></h2><p>{esc(a["summary"])}</p><small>21 October 2026 · HCMC information desk</small><a href="./article-{a["slug"]}.html">Read article ↗</a></article>' for a in articles)
controls='<div class="wrap search-controls"><label>Search articles<input id="content-search" type="search" placeholder="Search topics or titles"></label><label>Category<select id="content-filter"><option value="">All topics</option><option>Everyday wellbeing</option><option>Clinic guide</option></select></label><p id="search-status" role="status"></p></div>'
page('blog.html','Clinic blog','Practical wellbeing articles and guides to visiting Healthy Concept Medical Centre, Montego Bay.',intro('THE HEALTHY CONCEPT JOURNAL','Read well.<br>Live informed.','Short reads for everyday wellbeing and a more confident clinic visit. Health articles link to their original sources.')+controls+f'<section class="wrap hub-grid" id="filter-grid">{cards}</section><p class="wrap fine">General education prepared by the HCMC information desk; no clinician review is claimed. <a href="./feed.xml">Subscribe using an RSS reader ↗</a></p>')
for a in articles:
 body=intro(a['category'].upper(),esc(a['title']),esc(a['summary']))
 body+='<article class="wrap article-body"><p class="fine">Published 21 October 2026 · HCMC information desk</p>'+''.join('<p>'+esc(p)+'</p>' for p in a['paragraphs'])
 body+='<aside class="editorial-note"><strong>Read the original source</strong><p>'+link(a['source'],a['sourceTitle'])+'</p><p>General information only. No clinician review is claimed. Ask your clinician about your individual circumstances.</p></aside><a href="./blog.html">← Back to the clinic blog</a></article>'
 page('article-'+a['slug']+'.html',a['title'],a['summary'],body)
news=[{'title':'Caribbean Wellness Day activities bring communities together','url':'https://www.moh.gov.jm/close-to-1800-participated-in-caribbean-wellness-day-activities/','date':'2026-10-09'}, {'title':'Ministry update on continuity of public healthcare','url':'https://www.moh.gov.jm/health-ministry-assures-public-of-continued-care-at-public-health-facilities/','date':'2026-10-09'},{'title':'Park Walker initiative and ageing fair','url':'https://www.moh.gov.jm/park-walker-initiative-comes-to-corporate-area-with-ageing-fair/','date':'2026-10-09'}]
(D/'news-fallback.json').write_text(json.dumps(news,indent=2))
newsCards=''.join(f'<article class="hub-card"><p class="eyebrow">MINISTRY OF HEALTH & WELLNESS</p><time datetime="{n["date"]}">9 October 2026</time><h2>{link(n["url"],n["title"])}</h2><p>Read the original Ministry update.</p></article>' for n in news)
page('news.html','Health news','Official Jamaican health updates, source links and clinic news.',intro('KNOW WHAT’S HAPPENING','Health news.<br>From the source.','Follow official public-health updates and discover new articles from the clinic.')+'<section class="wrap"><div class="news-toolbar"><p id="news-status" role="status">Selected official updates · checked 21 October 2026. Checking the Ministry feed…</p><button class="button small" id="refresh-news">Refresh feed</button></div><div id="news-grid" class="hub-grid">'+newsCards+'</div><p class="fine">Headlines link to the original publisher. A source date is not a clinic announcement or an endorsement. If the feed is unavailable, selected dated links remain visible.</p><p>'+link('https://www.moh.gov.jm/press-releases/','All Ministry press releases')+'</p></section><section class="wrap editorial-note"><h2>From our clinic</h2><p>Our patient website now supports appointment requests and links to TEC Healthcare for staff. General consultations start at JA$3,000.</p><a href="./blog.html">Explore the clinic blog ↗</a></section>')
places=[('Healthy Concept Medical Centre','General practice','58 Barnett Street, Montego Bay','876 669 5974','./index.html#care','Our clinic'),('Cornwall Regional Hospital','Hospital','Mount Salem, Montego Bay','876 952 5100','https://www.wrha.gov.jm/health-facilities/st-james/','WRHA listing'),('Montego Bay Comprehensive Health Centre','Health centre','Creek Street, Montego Bay','876 979 7820','https://www.wrha.gov.jm/health-facilities/st-james/','WRHA listing'),('Catherine Hall Health Centre','Health centre','Westgreen, Catherine Hall, Montego Bay','876 952 0396','https://www.wrha.gov.jm/health-facilities/st-james/','WRHA listing'),('Mount Salem Health Centre','Health centre','Montego Bay 2 P.O.','876 979 6015','https://www.wrha.gov.jm/health-facilities/st-james/','WRHA listing'),('St. James Health Department','Public health','Payne Street, Montego Bay','876 979 7820','https://www.wrha.gov.jm/health-facilities/st-james/','WRHA listing')]
placesHtml=''.join(f'<article class="hub-card filterable" data-category="{cat}"><p class="eyebrow">{cat}</p><h2>{name}</h2><p>{addr}</p><p><a href="tel:+1{tel.replace(" ","")}">+1 {tel}</a></p>{link(url,label)}</article>' for name,cat,addr,tel,url,label in places)
controls='<div class="wrap search-controls"><label>Search local services<input id="content-search" type="search" placeholder="Name, area or service"></label><label>Service type<select id="content-filter"><option value="">All services</option>'+''.join(f'<option>{cat}</option>' for cat in ['General practice','Hospital','Health centre','Public health'])+'</select></label><p id="search-status" role="status"></p></div>'
page('local-services.html','Local health services','Find clinic, hospital and public health service contacts in Montego Bay and St James.',intro('MONTEGO BAY & ST JAMES','Find care<br>in your community.','A starting point for local health services. Call the provider to confirm current services, clinic schedules, location and fees.')+controls+'<section class="wrap hub-grid" id="filter-grid">'+placesHtml+'</section><section class="wrap editorial-note"><p>External contacts are drawn from the Western Regional Health Authority directory, checked 21 October 2026. Listings are informational and do not imply a partnership. This is not a live capacity or emergency-dispatch directory.</p>'+link('https://www.wrha.gov.jm/health-facilities/st-james/','Full St James facilities directory')+'<p>For a medical emergency, seek immediate help through local emergency services or the nearest emergency department. Do not wait for a website reply.</p></section>')
# RSS subscription has no email list and collects no patient data.
items=''.join(f'<item><title>{xml(a["title"])}</title><link>{BASE}article-{a["slug"]}.html</link><guid>{BASE}article-{a["slug"]}.html</guid><description>{xml(a["summary"])}</description><pubDate>Wed, 21 Oct 2026 12:00:00 GMT</pubDate></item>' for a in articles)
(D/'feed.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>Healthy Concept Medical Centre — Clinic Blog</title><link>'+BASE+'blog.html</link><description>Clinic guides and general wellbeing information from Montego Bay.</description>'+items+'</channel></rss>')
files=['','health.html','blog.html','news.html','local-services.html']+['article-'+a['slug']+'.html' for a in articles]
(D/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+BASE+f+'</loc></url>' for f in files)+'</urlset>')
(D/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+BASE+'sitemap.xml\n')
print('Generated health hub, blog, articles, news, directory, RSS and sitemap.')
